import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Mistral AI (BYOK Provider)","description":"","frontmatter":{"title":"Mistral AI (BYOK Provider)"},"headers":[],"relativePath":"providers/mistral-ai.md","filePath":"providers/mistral-ai.md"}`),a={name:`providers/mistral-ai.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="mistral-ai-mode-byok" tabindex="-1">Mistral AI (Mode BYOK) <a class="header-anchor" href="#mistral-ai-mode-byok" aria-label="Permalink to “Mistral AI (Mode BYOK)”">​</a></h1><p><strong>Mistral AI</strong> pilihan yang patut dipertimbangkan untuk BYOK: provider Eropa yang terbuka, punya <em>free tier</em> bernama plan <strong>Experiment</strong> untuk mencoba tanpa kartu kredit, dan keluarga model yang tertata rapi — dari yang paling murah untuk chat harian sampai model premium. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Aplikasi chat konsumen Mistral kini bernama <strong>Vibe</strong> (dulu Le Chat). Hati-hati: ini <strong>dua dunia yang berbeda</strong> — langganan Le Chat/Vibe <strong>tidak memberikan kuota API</strong>. Akses API hanya lewat <em>La Plateforme</em> (console Mistral). Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan angka harga — cek halaman resmi <a href="https://mistral.ai/pricing/" target="_blank" rel="noreferrer">harga Mistral</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Daftar di <a href="https://console.mistral.ai" target="_blank" rel="noreferrer">console.mistral.ai</a> — bisa dengan email atau OAuth (Google, GitHub, Microsoft, Apple).</li><li>Saat masuk pertama kali, buat <strong>Workspace</strong> (personal atau team) dan terima <em>Terms of Service</em>. Kadang diminta verifikasi nomor HP saat memilih plan.</li><li>Setelah itu, wajib <strong>mengaktifkan plan di Billing</strong> — lihat kotak di bawah, ini langkah yang paling sering terlewat.</li><li>Buka Admin Panel → <strong>API Keys</strong> → <strong>Create new key</strong>. Isi nama/label (opsional) dan <strong>expiration date</strong>.</li><li>Key ditampilkan <strong>sekali saja</strong> dalam modal — salin dan simpan di tempat aman.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Wajib: aktifkan plan di Billing dulu</p><p>Ini <strong>perangkap paling umum</strong> di Mistral: sebelum API key bisa dipakai, kamu <strong>wajib mengaktifkan plan</strong> lewat <em>Administration → Billing</em> — <strong>termasuk</strong> pada plan gratis <strong>Experiment</strong> (tanpa kartu kredit). Kalau langkah ini terlewat, key berhasil dibuat tapi setiap API call gagal <strong>401</strong> padahal key-nya &quot;benar&quot;. Plan <strong>Scale</strong> adalah <em>pay-as-you-go</em> yang memerlukan kartu kredit.</p><p>Referensi resmi: <a href="https://docs.mistral.ai/admin/billing-usage/usage-limits" target="_blank" rel="noreferrer">billing &amp; usage</a> di docs Mistral.</p></div><div class="tip custom-block"><p class="custom-block-title">🔐 Pakai expiration + rotasi</p><p>Saat membuat key, isi <strong>expiration date</strong> dan biasakan <strong>rotasi berkala</strong> — buat key baru, ganti di Mikazuki, lalu hapus key lama. Kalau key terlewat tampilannya, satu-satunya solusi adalah membuat key baru (dan jangan pernah meng-commit key ke repository).</p></div><hr><h2 id="mengaktifkan-mistral-ai-di-mikazuki-ai" tabindex="-1">Mengaktifkan Mistral AI di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-mistral-ai-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Mistral AI di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Mistral AI:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>Mistral AI</strong>.</li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis dari key kamu.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>, lalu klik simpan.</li></ol><p>Worker Mikazuki memakai <strong>endpoint Mistral AI native</strong>, jadi tidak ada kolom <em>Base URL</em> untuk diisi — titik akhirnya fixed.</p><div class="tip custom-block"><p class="custom-block-title">Sudah baik dari sananya</p><p>Default <strong>temperature 0.85</strong> Mikazuki sudah cocok untuk Mistral AI; kamu tidak perlu mengubahnya kecuali memang ingin gaya jawaban yang berbeda.</p></div><hr><h2 id="context-window" tabindex="-1">Context Window <a class="header-anchor" href="#context-window" aria-label="Permalink to “Context Window”">​</a></h2><p>Context window Mistral berbeda-beda per model — model terbaru umumnya penyediaannya luas, tapi angka pastinya ikut model yang aktif di daftar fetch models kamu:</p><ul><li><strong>Model terbaru</strong> → kapasitas besar; kalau yakin dengan modelnya, preset <code>1M</code> bisa dipertimbangkan bila memang didukung.</li><li><strong>Kalau ragu</strong> → mulai dari preset <code>128K</code>, cek spesifikasi model di daftar fetch models, baru naikkan.</li></ul><p>Detail cara kerja <code>context_window</code>, <em>Reserved Output</em>, dan preset chip ada di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>.</p><div class="tip custom-block"><p class="custom-block-title">💡 Optimalkan ruang jawaban</p><p>Menaikkan <code>max_tokens</code> memberi jawaban ruang lebih besar — ingat bahwa <code>max_tokens</code> ikut dipotong dari context window, jadi naikkan <code>context_window</code>-nya juga bila perlu.</p></div><hr><h2 id="free-tier-harga" tabindex="-1">Free Tier &amp; Harga <a class="header-anchor" href="#free-tier-harga" aria-label="Permalink to “Free Tier &amp; Harga”">​</a></h2><ul><li><strong>Free tier = plan Experiment</strong>: cukup untuk <em>prototyping</em> dan obrolan pribadi, tanpa kartu kredit. Konsekuensinya: ada <strong>kuota pemakaian bulanan</strong> dan <strong>rate limit yang rendah</strong>.</li><li>Untuk pemakaian lebih bebas, naik ke plan <strong>Scale</strong> (<em>pay-as-you-go</em>, wajib kartu kredit).</li><li><strong>Harga</strong> dibedakan per juta token dan berbeda per model. Keluarga modelnya: <strong>Small</strong> (paling murah), <strong>Medium</strong> (kelas menengah), <strong>Large</strong> (premium), plus <strong>Codestral</strong> yang khusus untuk kode.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka</p><p>Kami sengaja tidak mencantumkan tabel harga di halaman ini — angkanya cepat basi. Cek halaman resmi <a href="https://mistral.ai/pricing/" target="_blank" rel="noreferrer">harga Mistral</a> dan dokumentasi <a href="https://docs.mistral.ai/admin/billing-usage/usage-limits" target="_blank" rel="noreferrer">usage limits</a> untuk angka terkini. Aturan praktis yang aman: <strong>Small</strong> untuk chat harian yang hemat, <strong>Medium</strong> untuk keseimbangan, <strong>Large</strong> untuk kualitas terbaik yang kamu bayar mahal.</p></div><hr><h2 id="rate-limit-spend-cap" tabindex="-1">Rate Limit &amp; Spend Cap <a class="header-anchor" href="#rate-limit-spend-cap" aria-label="Permalink to “Rate Limit &amp; Spend Cap”">​</a></h2><p>Batasan Mistral dihitung <strong>per Organization</strong>, bukan per key, dan diukur <strong>per model</strong>:</p><ul><li><strong>Rate limit per model</strong> — gabungan <em>tokens per minute</em> (TPM) dan <em>requests per second</em> (RPS).</li><li><strong>Spend limit bulanan</strong> — berlaku di level Organization dan juga Workspace (<em>Administration → Workspaces</em>; kelola lewat <em>Subscriptions → Billing</em> di Admin Panel). Mentok spend limit? <strong>API bisa dinonaktifkan</strong> sampai bulan berikutnya, atau sampai admin menaikkan limit.</li></ul><p>(Di free tier Experiment, kuota bulanan dan rate limit rendah berlaku di atas semua itu — lihat bagian sebelumnya.)</p><p>Angka limit terkini selalu cek langsung di <strong>Admin Panel → API → Limits</strong>.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Error 401 padahal key baru dibuat</summary><p>Hampir selalu karena <strong>plan di Billing belum diaktifkan</strong> — perangkap paling umum di Mistral (lihat kotak danger di atas). Buka <em>Administration → Billing</em>, aktifkan plan (Experiment pun wajib), lalu ulangi request-nya. Kalau sudah aktif, cek juga key salah tempel / terpotong atau sudah lewat <em>expiration</em>.</p></details><details class="details custom-block"><summary>Error 429 — terlalu sering</summary><p>Free tier Experiment punya limit ketat — aturan praktis komunitasnya sekitar <strong>1 request per detik per key</strong>, berlaku global. Turunkan intensitas request, atau upgrade ke plan <strong>Scale</strong> untuk limit yang lebih longgar. Di plan berbayar, ingat limitnya diukur <strong>per model</strong> (TPM + RPS) dan <strong>per Organization</strong> — membuat key baru tidak menolong.</p></details><details class="details custom-block"><summary>Error 404 / model tidak valid</summary><p>Nama model salah — pakai daftar dari tombol 🔍 <strong>fetch models</strong>, jangan ketik manual (mudah salah kapital atau salah format). Kalau fetch gagal sesaat, retry tombol fetch dulu sebelum isi kolom model secara <strong>manual</strong>.</p></details><details class="details custom-block"><summary>Jawaban terpotong / berhenti di tengah</summary><p><code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> mungkin terlalu kecil. Naikkan nilainya — tapi ingat <code>max_tokens</code> juga dipotong dari context window sebagai <em>Reserved Output</em>, jadi jangan set berlebihan tanpa menaikkan <code>context_window</code>.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./claude.html">Anthropic Claude</a> — panduan padanan untuk provider Claude.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,39)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};